var phase: number = 0; // 0=初创经济 1=扩张占矿 2=转军事


// ===== 工具函数 =====

function unitCost(t: string): number {
  if (t === "worker") return 4;
  if (t === "melee") return 8;
  if (t === "ranged") return 12;
  return 16;
}

function countType(
  arr: readonly { type: string }[],
  type: string,
): number {
  let n = 0;
  for (let i = 0; i < arr.length; i += 1) {
    const u = arr[i];
    if (u !== undefined && u.type === type) n += 1;
  }
  return n;
}

function nearestSite(
  x: number,
  y: number,
  sites: readonly { x: number; y: number }[],
): { x: number; y: number; id: number } | null {
  let best: { x: number; y: number; id: number } | null = null;
  let bestR = 0;
  for (let i = 0; i < sites.length; i += 1) {
    const s = sites[i];
    if (s === undefined) continue;
    const r = getRange(x, y, s.x, s.y);
    if (best === null || r < bestR) {
      best = { x: s.x, y: s.y, id: (s as any).id };
      bestR = r;
    }
  }
  return best;
}


