```typescript
// =====================================================
// script.ts
// 策略取向：B 扩张运营
//   优先占资源点与扩张经济，攒够家底再转军事
// =====================================================

// 跨 tick 记忆：只放数值
var myIndexCached: number = -1;

// 阈值（数值常量）
const TARGET_WORKERS = 6;   // 目标农民数
const TARGET_MELEE = 6;     // 软上限：先攒到这些再扩
const CARRY_LIMIT = 20;     // 满载阈值
const HARVEST_RANGE = 1;    // 采集/交付/攻击射程（按兵种另算）

function loop(): void {
  const me = getMyIndex();
  if (myIndexCached === -1) myIndexCached = me;

  // 读本 tick 快照（每 tick 都重读）
  const players = getObjectsByType("player");
  const mePlayer = players[me];
  if (mePlayer === undefined) return;
  if (!mePlayer.alive) return;
  const myRes: number = mePlayer.resources;

  const myUnits = getObjectsByType("unit", { owner: me });
  const myBases = getObjectsByType("site", { owner: me, kind: "base" });
  const myResSites = getObjectsByType("site", { owner: me, kind: "resource" });
  const neutralResSites = getObjectsByType("site", { owner: -1, kind: "resource" });

  // 计数
  let workerN = 0;
  let meleeN = 0;
  for (let i = 0; i < myUnits.length; i += 1) {
    const u = myUnits[i];
    if (u === undefined) continue;
    if (u.type === "worker") workerN += 1;
    else if (u.type === "melee") meleeN += 1;
  }

  // ---- 生产：每个基地独立产线，空才下单 ----
  for (let i = 0; i < myBases.length; i += 1) {
    const base = myBases[i];
    if (base === undefined) continue;
    if (base.producing !== null) continue;

    let toSpawn: string = "";
    if (workerN < TARGET_WORKERS && myRes >= 4) {
      toSpawn = "worker";
    } else if (meleeN < TARGET_MELEE && myRes >= 12) {
      toSpawn = "melee";
    } else if (myRes >= 16) {
      // 都达标了继续补兵
      toSpawn = "melee";
    }

    if (toSpawn === "") continue;
    spawnUnit(base.id, toSpawn);
  }

  // ---- 给每个单位下一条意图 ----
  for (let i = 0; i < myUnits.length; i += 1) {
    const u = myUnits[i];
    if (u === undefined) continue;

    if (u.type === "worker") {
      actWorker(u, myBases, myResSites, neutralResSites, me);
    } else {
      actCombat(u, me);
    }
  }
}

// ---- 工具：找最近对象 ----
function findClosestSite(
  x: number,
  y: number,
  sites: readonly { x: number; y: number; id?: number }[],
): { x: number; y: number; id: number } | null {
  let best: { x: number; y: number; id: number } | null = null;
  let bestR = 0;
  for (let i = 0; i < sites.length; i += 1) {
    const s = sites[i];
    if (s === undefined) continue;
    const r = getRange(x, y, s.x, s.y);
    if (best === null || r < bestR) {
      best = { x: s.x, y: s.y, id: s.id !== undefined ? s.id : -1 };
      bestR = r;
    }
  }
  return best;
}

// ---- 农民行为：采集 → 满载回家 → 交付；没矿时去占中立 ----
function actWorker(
  u: { id: number; x: number; y: number; carrying: number },
  myBases: readonly { x: number; y: number; id?: number }[],
  myResSites: readonly { x: number; y: number; remaining?: number; id?: number }[],
  neutralResSites: readonly { x: number; y: number; progressOwner: number; id?: number }[],
  me: number,
): void {
  // 满载：回家交付
  if (u.carrying >= CARRY_LIMIT) {
    const base = findClosestSite(u.x, u.y, myBases);
    if (base === null) return;
    if (getRange(u.x, u.y, base.x, base.y) <= 1) {
      transfer(u.id);
    } else {
      moveTo(u.id, base.x, base.y);
    }
    return;
  }

  // 找最近的己方有储量资源点
  let target: { x: number; y: number; id: number; dist: number } | null = null;
  for (let i = 0; i < myResSites.length; i += 1) {
    const s = myResSites[i];
    if (s === undefined) continue;
    if (s.remaining === undefined) continue;
    if (s.remaining <= 0) continue;
    const r = getRange(u.x, u.y, s.x, s.y);
    if (target === null || r < target.dist) {
      target = { x: s.x, y: s.y, id: s.id !== undefined ? s.id : -1, dist: r };
    }
  }

  if (target !== null) {
    if (target.dist <= 1) {
      harvest(u.id, target.id);
    } else {
      moveTo(u.id, target.x, target.y);
    }
    return;
  }

  // 没可采的己方资源：找最近可占的中立（仅当没人占或我在占）
  let cap: { x: number; y: number; id: number; dist: number } | null = null;
  for (let i = 0; i < neutralResSites.length; i += 1) {
    const s = neutralResSites[i];
    if (s === undefined) continue;
    if (s.progressOwner !== -1 && s.progressOwner !== me) continue;
    const r = getRange(u.x, u.y, s.x, s.y);
    if (cap === null || r < cap.dist) {
      cap = { x: s.x, y: s.y, id: s.id !== undefined ? s.id : -1, dist: r };
    }
  }

  if (cap === null) return;

  if (cap.dist <= 1) {
    // 已站在相邻格：累加占领进度，不下任何动作
    return;
  }
  moveTo(u.id, cap.x, cap.y);
}

// ---- 战斗单位行为 ----
function actCombat(
  u: { id: number; x: number; y: number; type: string },
  me: number,
): void {
  // 找最近的敌方单位
  let foe: { id: number; x: number; y: number; dist: number } | null = null;
  for (let p = 0; p < 4; p += 1) {
    if (p === me) continue;
    const foes = getObjectsByType("unit", { owner: p });
    for (let i = 0; i < foes.length; i += 1) {
      const f = foes[i];
      if (f === undefined) continue;
      const r = getRange(u.x, u.y, f.x, f.y);
      if (foe === null || r < foe.dist) {
        foe = { id: f.id, x: f.x, y: f.y, dist: r };
      }
    }
  }

  // 攻击射程：近战/骑兵 1，远程 2
  const myRange = u.type === "ranged" ? 2 : 1;

  if (foe !== null && foe.dist <= myRange) {
    attack(u.id, foe.id);
    return;
  }

  if (foe !== null) {
    moveTo(u.id, foe.x, foe.y);
    return;
  }

  // 没敌人：去最近的敌方基地
  let foeBase: { x: number; y: number } | null = null;
  let foeBaseR = 0;
  for (let p = 0; p < 4; p += 1) {
    if (p === me) continue;
    const foeBases = getObjectsByType("site", { owner: p, kind: "base" });
    for (let i = 0; i < foeBases.length; i += 1) {
      const b = foeBases[i];
      if (b === undefined) continue;
      const r = getRange(u.x, u.y, b.x, b.y);
      if (foeBase === null || r < foeBaseR) {
        foeBase = { x: b.x, y: b.y };
        foeBaseR = r;
      }
    }
  }
  if (foeBase !== null) moveTo(u.id, foeBase.x, foeBase.y);
}
```

