```typescript
// ============================================================
// script.ts
// 策略取向：B 扩张运营
//   优先占资源点与扩张经济，攒够家底再转军事
// ============================================================

// ---- 跨 tick 记忆：只放数值 ----
var myIndexCached: number = -1;

// ---- 类型视图（结构性子集，避免 any） ----
type SiteView = {
  id: number;
  kind: "base" | "resource";
  x: number;
  y: number;
  owner: number;
  progressOwner: number;
  progress: number;
  remaining?: number;
  producing: { type: string; remainingTicks: number } | null;
};

type UnitView = {
  id: number;
  owner: number;
  type: string;
  x: number;
  y: number;
  hp: number;
  carrying: number;
};

// ---- 阈值 ----
const TARGET_WORKERS = 6;
const TARGET_MELEE = 6;
const CARRY_LIMIT = 20;

// ---- 主循环 ----
function loop(): void {
  const me = getMyIndex();
  if (myIndexCached === -1) myIndexCached = me;

  // 本 tick 玩家状态
  const players = getObjectsByType("player");
  const mePlayer = players[me];
  if (mePlayer === undefined) return;
  if (!mePlayer.alive) return;
  const myRes: number = mePlayer.resources;

  // 本 tick 快照
  const myUnits = getObjectsByType("unit", { owner: me }) as UnitView[];
  const myBases = getObjectsByType("site", { owner: me, kind: "base" }) as SiteView[];
  const myResSites = getObjectsByType("site", { owner: me, kind: "resource" }) as SiteView[];
  const neutralSites = getObjectsByType("site", { owner: -1, kind: "resource" }) as SiteView[];

  // 预取敌方（避免每单位重查）
  const foeUnits: UnitView[][] = [[], [], [], []];
  const foeBases: SiteView[][] = [[], [], [], []];
  for (let p = 0; p < 4; p += 1) {
    if (p === me) continue;
    foeUnits[p] = getObjectsByType("unit", { owner: p }) as UnitView[];
    foeBases[p] = getObjectsByType("site", { owner: p, kind: "base" }) as SiteView[];
  }

  // 计数
  let workerN = 0;
  let meleeN = 0;
  for (let i = 0; i < myUnits.length; i += 1) {
    const u = myUnits[i];
    if (u === undefined) continue;
    if (u.type === "worker") workerN += 1;
    else if (u.type === "melee") meleeN += 1;
  }

  // ---- 生产：每个基地独立产线，空才下单 ----
  for (let i = 0; i < myBases.length; i += 1) {
    const base = myBases[i];
    if (base === undefined) continue;
    if (base.producing !== null) continue;

    let toSpawn = "";
    if (workerN < TARGET_WORKERS && myRes >= 4) {
      toSpawn = "worker";
    } else if (meleeN < TARGET_MELEE && myRes >= 12) {
      toSpawn = "melee";
    } else if (myRes >= 16) {
      // 都达标后继续扩军
      toSpawn = "melee";
    }

    if (toSpawn === "") continue;
    spawnUnit(base.id, toSpawn);
  }

  // ---- 给每个单位一条意图 ----
  for (let i = 0; i < myUnits.length; i += 1) {
    const u = myUnits[i];
    if (u === undefined) continue;
    if (u.type === "worker") {
      actWorker(u, myBases, myResSites, neutralSites, me);
    } else {
      actCombat(u, me, foeUnits, foeBases);
    }
  }
}

// ---- 农民行为：满载交付 / 找资源点采集 / 没矿去占 ----
function actWorker(
  u: UnitView,
  myBases: SiteView[],
  myResSites: SiteView[],
  neutralSites: SiteView[],
  me: number,
): void {
  // 满载：找最近的己方基地
  if (u.carrying >= CARRY_LIMIT) {
    const b = findClosestId(u.x, u.y, myBases);
    if (b === null) return;
    if (getRange(u.x, u.y, b.x, b.y) <= 1) {
      transfer(u.id);
    } else {
      moveTo(u.id, b.x, b.y);
    }
    return;
  }

  // 空载：找最近的己方有储量资源点
  const target = findOwnedWithResource(u.x, u.y, myResSites);
  if (target !== null) {
    if (getRange(u.x, u.y, target.x, target.y) <= 1) {
      harvest(u.id, target.id);
    } else {
      moveTo(u.id, target.x, target.y);
    }
    return;
  }

  // 没可采己方资源：找最近的未被他方占的中立资源点去占领
  const cap = findCapturableNeutral(u.x, u.y, neutralSites, me);
  if (cap === null) return;
  if (getRange(u.x, u.y, cap.x, cap.y) <= 1) {
    // 站在相邻格让进度累加：本 tick 不下任何动作
    return;
  }
  moveTo(u.id, cap.x, cap.y);
}

// ---- 战斗单位：找最近敌人（射程内攻击，否则靠近）；无敌人去最近敌方基地 ----
function actCombat(
  u: UnitView,
  me: number,
  foeUnits: UnitView[][],
  foeBases: SiteView[][],
): void {
  let foe: { id: number; x: number; y: number; dist: number } | null = null;
  for (let p = 0; p < 4; p += 1) {
    if (p === me) continue;
    const list = foeUnits[p];
    for (let i = 0; i < list.length; i += 1) {
      const f = list[i];
      if (f === undefined) continue;
      const d = getRange(u.x, u.y, f.x, f.y);
      if (foe === null || d < foe.dist) {
        foe = { id: f.id, x: f.x, y: f.y, dist: d };
      }
    }
  }

  const myRange = u.type === "ranged" ? 2 : 1;
  if (foe !== null && foe.dist <= myRange) {
    attack(u.id, foe.id);
    return;
  }
  if (foe !== null) {
    moveTo(u.id, foe.x, foe.y);
    return;
  }

  // 没敌人：去最近的敌方基地
  let foeBase: { x: number; y: number } | null = null;
  let foeBaseR = 0;
  for (let p = 0; p < 4; p += 1) {
    if (p === me) continue;
    const list = foeBases[p];
    for (let i = 0; i < list.length; i += 1) {
      const b = list[i];
      if (b === undefined) continue;
      const d = getRange(u.x, u.y, b.x, b.y);
      if (foeBase === null || d < foeBaseR) {
        foeBase = { x: b.x, y: b.y };
        foeBaseR = d;
      }
    }
  }
  if (foeBase !== null) moveTo(u.id, foeBase.x, foeBase.y);
}

// ---- 工具：最近对象 ----
function findClosestId(
  x: number,
  y: number,
  arr: { x: number; y: number; id: number }[],
): { x: number; y: number; id: number } | null {
  let best: { x: number; y: number; id: number } | null = null;
  let bestR = 0;
  for (let i = 0; i < arr.length; i += 1) {
    const s = arr[i];
    if (s === undefined) continue;
    const r = getRange(x, y, s.x, s.y);
    if (best === null || r < bestR) {
      best = s;
      bestR = r;
    }
  }
  return best;
}

function findOwnedWithResource(
  x: number,
  y: number,
  arr: SiteView[],
): { x: number; y: number; id: number } | null {
  let best: { x: number; y: number; id: number } | null = null;
  let bestR = 0;
  for (let i = 0; i < arr.length; i += 1) {
    const s = arr[i];
    if (s === undefined) continue;
    if (s.remaining === undefined) continue;
    if (s.remaining <= 0) continue;
    const r = getRange(x, y, s.x, s.y);
    if (best === null || r < bestR) {
      best = { x: s.x, y: s.y, id: s.id };
      bestR = r;
    }
  }
  return best;
}

function findCapturableNeutral(
  x: number,
  y: number,
  arr: SiteView[],
  me: number,
): { x: number; y: number; id: number } | null {
  let best: { x: number; y: number; id: number } | null = null;
  let bestR = 0;
  for (let i = 0; i < arr.length; i += 1) {
    const s = arr[i];
    if (s === undefined) continue;
    if (s.progressOwner !== -1 && s.progressOwner !== me) continue;
    const r = getRange(x, y, s.x, s.y);
    if (best === null || r < bestR) {
      best = { x: s.x, y: s.y, id: s.id };
      bestR = r;
    }
  }
  return best;
}
