  // ---- 每个单位一条意图 ----
  for (let i = 0; i < myUnits.length; i += 1) {
    const u = myUnits[i];
    if (u === undefined) continue;
    if (u.type === "worker") {
      actWorker(u, myBases, myResSites, neutralSites, me);
    } else {
      actCombat(u, me, foeUnits, foeBases);
    }
  }
}

function actWorker(
  u: any,
  myBases: any[],
  myResSites: any[],
  neutralSites: any[],
  me: number,
): void {
